INSERT IGNORE INTO daily_messages (daily_messages_id, content) VALUES
(1, '오늘 하루도 수고했어요. 당신은 충분히 잘하고 있어요.'),
(2, '작은 한 걸음이 큰 변화를 만듭니다.'),
(3, '지금 이 순간, 충분히 잘하고 있습니다.'),
(4, '고민은 나를 성장시키는 밑거름입니다.'),
(5, '오늘 할 수 있는 일을 내일로 미루지 마세요.');
INSERT IGNORE INTO recipes (recipe_id, user_id, title, description, estimated_minutes, created_at, updated_at, is_deleted) VALUES
(1,  NULL, '심호흡 5번 하기',           '눈을 감고 코로 깊게 들이마시고 입으로 천천히 내뱉는 심호흡을 5번 반복합니다.', 2,  NOW(), NOW(), false),
(2,  NULL, '스트레칭 하기',             '양손을 깍지 끼고 하늘 위로 기지개를 쭉 켭니다. 천천히 내쉬며 뭉쳐있던 목과 어깨를 부드럽게 돌려주고, 온몸의 근육이 이완되는 감각에 집중해 봅니다.', 5,  NOW(), NOW(), false),
(3,  NULL, '눈 감고 1분 명상',          '화면을 끄고 가만히 눈을 감은 채, 들고나는 숨소리에만 온전히 집중해 봅니다.', 1,  NOW(), NOW(), false),
(4,  NULL, '딱 10초 동안 제자리 털기', '제자리에서 손끝과 발끝, 온몸을 온 힘을 다해 자잘하게 탈탈탈 털어내며 몸의 모든 긴장과 걱정을 날려 보냅니다.', 1,  NOW(), NOW(), false),
(5,  NULL, '오감 그라인딩 실행하기',    '수행 방법: 현재의 감각에 집중히며 마음을 차분히 가라앉히는 5단계 불안 대처 수행법입니다. 현재 눈에 보이는 것 5가지, 촉각 4가지, 소리 3가지, 냄새 2가지, 맛 1가지를 차례로 천천히 찾아보며 현실에 집중해 봅니다.', 5,  NOW(), NOW(), false),
(6,  NULL, '찬물 한 컵 마시기',         '시원한 물 한 컵을 준비해 목 넘김과 차가운 온도를 천천히 음미하며 마십니다.', 2,  NOW(), NOW(), false),
(7,  NULL, '시원한 물로 세수하기',      '화장실로 가서 찬물로 세수를 하거나 손을 깨끗이 씻으며 기분을 리프레시합니다.', 3,  NOW(), NOW(), false),
(8,  NULL, '룸 스프레이 뿌리기',        '공간에 좋아하는 향이나 마음이 편안해지는 아로마 스프레이를 분사하고 향을 깊게 들이마십니다.', 1,  NOW(), NOW(), false),
(9,  NULL, '가볍게 동네 산책하기',      '편한 신발을 신고 밖으로 나가 가볍게 동네 한 바퀴를 걸으며 바깥 공기를 쐽니다.', 15, NOW(), NOW(), false),
(10, NULL, '창문 열고 환기하기',        '창문을 활짝 열고 바깥 풍경을 바라보며 시원한 바람을 3번 크게 들이마십니다.', 3,  NOW(), NOW(), false),
(11, NULL, '책상 정리정돈하기',         '눈앞에 흩어진 펜, 종이, 쓰레기 등을 제자리에 치우며 주변 환경을 깔끔하게 정돈합니다.', 5,  NOW(), NOW(), false),
(12, NULL, '귀여운 동물 영상 보기',     '귀여운 강아지나 고양이 등 동물이 나오는 짧은 클립 영상을 보며 소소하게 힐링합니다.', 5,  NOW(), NOW(), false),
(13, NULL, '지금 기분에 어울리는 노래 찾기', '음원 앱이나 유튜브를 켜고 내 마음을 대변해 주거나 기분을 환기해 줄 노래 딱 1곡을 골라 가사에 집중하며 끝까지 감상합니다.', 5,  NOW(), NOW(), false),
(14, NULL, '좋아하는 음악 듣기',        '마음이 편안해지는 잔잔한 음악이나 평소 좋아하는 최애 곡을 1곡 끝까지 감상합니다.', 5,  NOW(), NOW(), false),
(15, NULL, '가사 없이 빗소리만 듣기',   'ASMR 장작 타는 소리나 잔잔한 빗소리를 검색해 틀어두고, 아무 생각 없이 소리의 결에만 귀를 기울입니다.', 5,  NOW(), NOW(), false),
(16, NULL, '나만의 플레이리스트 만들기/재정비하기', '들으면 마음이 편안해지는 노래들을 모아 새 플레이리스트를 만들고 이름을 붙여줍니다. 또는 이미 만든 플레이리스트를 재정비합니다.', 15, NOW(), NOW(), false),
(17, NULL, '마음에 꽂히는 책 문장 필사하기', '근처 책이나 좋아하는 시집을 아무 페이지나 펼쳐서, 마음에 닿는 문장 딱 한 줄을 정성스럽게 종이에 꾹꾹 눌러 적어봅니다.', 3,  NOW(), NOW(), false),
(18, NULL, '오늘의 날씨를 아주 자세히 묘사하기', '메모장을 켜고 단순히 맑음, 흐림 대신 소설가처럼 지금 이 순간의 날씨를 한 문장으로 적어봅니다.', 3,  NOW(), NOW(), false),
(19, NULL, '창밖 하늘 사진 예쁘게 한 장 찍기', '창가로 다가가 지금 이 순간의 하늘이나 바깥 풍경을 가장 감성적인 구도로 찰칵 사진에 담아 앨범에 보관합니다.', 2,  NOW(), NOW(), false),
(20, NULL, '따뜻한 물로 샤워하기',      '따뜻한 온수를 틀고 물이 피부에 닿는 촉감과 온기에 집중해 보세요. 오늘 하루 쌓인 긴장을 물줄기와 함께 흘려보냅니다.', 20, NOW(), NOW(), false),
(21, NULL, '향기로운 바디로션으로 마사지하기', '샤워 후 좋아하는 향의 바디로션을 손바닥에 덜어 온기를 낸 뒤, 발끝부터 어깨까지 고생한 내 몸을 정성스럽게 쓸어내리며 발라줍니다.', 5,  NOW(), NOW(), false),
(22, NULL, '머리 빗질하며 생각 엉킴 풀기', '거울 앞에 앉아 끝이 둥근 빗으로 두피를 톡톡 두드려 마사지한 뒤, 엉킨 머리카락을 정성스레 빗어내립니다.', 3,  NOW(), NOW(), false),
(23, NULL, '따뜻한 물에 족욕하기',      '대야에 따뜻한 물을 받아 발을 담그고 가만히 앉아봅니다. 발끝에서부터 온몸으로 서서히 퍼져나가는 따뜻한 혈류에 집중해 보세요.', 15, NOW(), NOW(), false),
(24, NULL, '마스크팩 얹고 누워있기',    '냉장고에 넣어둔 시원한 마스크팩을 얼굴에 착 붙이고, 팩이 닿는 감각을 느끼며 침대에 편안히 누워 온몸의 힘을 빼봅니다.', 15, NOW(), NOW(), false),
(25, NULL, '따뜻한 차 마시기',          '좋아하는 따뜻한 티백이나 음료를 우려내어 향을 맡고 천천히 한 모금씩 마십니다.', 10, NOW(), NOW(), false),
(26, NULL, '따뜻한 우유나 두유 마시기', '따뜻하게 데운 우유나 두유를 머그잔에 담아, 컵을 양손으로 감싸 온기를 느낀 뒤 고소한 맛을 음미하며 천천히 마십니다.', 5,  NOW(), NOW(), false),
(27, NULL, '나를 위한 비타민 충전 시간', '좋아하는 비타민이나 영양제 한 알을 꺼내어 내 몸에 좋은 에너지를 선물한다는 마음으로 시원한 물과 함께 천천히 삼킵니다.', 1,  NOW(), NOW(), false);
